  "封筒型のポケットやVERDYが手掛けたキャラクター「Vick」を配した「Postal Jacket」（6万4900円）や「Postal Shirt」（4万7300円）をはじめ、エアメール風のグラフィックをあしらった「Air Mail Jacket」（7万5900円）、「Air Mail Shirt」（5万3900円）、「Air Mail Pants」（4万7300円）を揃えている。",

