  "Scott Bessent米財務長官は米国時間11月15日、NVIDIAの次期最高経営責任者（CEO）は社外から選ぶべきだとの考えを示した。米Fox Newsの番組「Sunday Morning Futures」で述べたもので、Reutersが同日伝えた。",

  "<strong>輸出管理体制の説明を要求</strong>Bessent長官は、社内で起きていたことを踏まえると大幅な刷新が必要だと主張した。あわせて、米国の輸出規制を守る企業文化があったかという問題について、取締役会と外部弁護士に今後10日以内の説明を求めた。",

  "AFPによると、長官は、実態の乏しい仲介企業を利用して中国への半導体販売規制を迂回していなかったかを問題にした。個人の私生活に関する問題よりも、会社の輸出管理の在り方を調べることが重要だと述べている。",

