  "同社はHarvey C. Jones氏を初の取締役会議長に選んだことも発表した。Jones氏は、Kress氏と経営陣を全面的に信頼しており、事業運営、顧客への約束、製品開発計画が中断なく続くと見込んでいると説明した。",

