    date: "11/16（月）",
    image: "img/ECBの政策手段、健全な財政運営の代替とはならず-クノット氏　経済.webp",
    imageClass: "img",
    paragraphs: [
  "（ブルームバーグ）:欧州中央銀行（ECB）による国債市場の安定化策は、各国の責任ある財政運営の代わりにはならない。次期ECB総裁候補でオランダ銀行前総裁のクノット氏がこうした考えを示した。",

  "<strong>財政運営</strong>15日付のイタリア紙コリエレ・デラ・セラのインタビューで、ECBの対応が「避けられない場面もある」と指摘した上で、「市場が無秩序に動く局面では、ECBが市場を支えることはできるが、それが健全な財政政策の代わりになるわけではない」と述べた。",

  "ラガルド総裁の後任を巡り、クノット氏はスペイン銀行前総裁のデコス氏と競っている。ラガルド氏は先月、8年間の任期満了を約9カ月残し、2027年2月7日に退任すると発表した。フランスの債務問題でユーロ圏危機の記憶がよみがえる中、総裁選びでは、金融市場の混乱や「債券自警団」への対応能力が決め手となる可能性がある。",

  "<strong>景気と物価</strong>クノット氏は「理想的な世界であれば、ECBがこうした重い役割を担う必要はもう少し減るのかもしれない」と発言。「金融政策と財政政策の足並みをそろえることが重要だ。ユーロ圏内で21カ国の政府がそれぞれ独立して財政政策を決める仕組みでは、それは一段と難しい。財政の持続可能性を守る強固な仕組みも必要だ」と語った。ドイツのメルツ首相は13日、ラガルド氏の後任を含むECB主要ポストの人事案を、ドイツが数日中に提示すると述べた。",

  "クノット氏は経済成長について、内需が非常に底堅く推移していると指摘。労働市場の堅調さや高水準の雇用、健全な民間部門のバランスシートも寄与したと説明した。防衛支出による一定の財政刺激に加え、主に米国発のAI投資ブームが生み出した世界的な需要も、ユーロ圏にプラスの波及効果をもたらしているという。",

  "インフレについては「警戒は必要だが、過度に懸念すべきではない」と発言。2026年初めにはインフレ率が目標に沿い、金利も中立的な水準にあったが、イランでの戦争によりエネルギー価格と短期的なインフレ率が押し上げられたと指摘した。今後の焦点は、主としてエネルギー価格のショックにとどまるのか、賃金や幅広い物価に波及し始めるのかだとした。"
]
