  "<strong>タイムトライアルの結果</strong>チームと個人で行われた3.3キロコースを走るタイムトライアルレースの女子は田中麗奈選手が5分2秒96、パラサイクリングでは木村和平選手と鶴見健二選手のペアが4分34秒52で勝利した。田中選手は今季最後のレースを1位で終え、「来季につながる結果になった。次回も出たい」と話した。（本田隼人）",

