    title: "みなみかわ、4カ月待ったシートカバーで社用車“デリカD:5”をカスタム⇒「だいぶイカつくなった」「オシャレ」",
    date: "11/16（月）",
    image: "img/みなみかわ　エンタメ.jpeg",
    imageClass: "img",
    paragraphs: [
  "タレントのみなみかわさんが11月10日、YouTubeチャンネル『みなみかわの術チャンネル』を更新。所属事務所「NANSE」の社用車「デリカD:5」をカスタムする様子を公開し、反響を呼んでいます。",

  "<strong>カスタムの希望を紹介</strong>今回、みなみかわさんは妻で「NANSE」の社長である雅代さんの希望を受け、社用車のデリカをカスタムするため、ショップ「V2STYLE」を訪れました。まずは、カスタムしたいポイントを説明します。雅代さんが真っ先に挙げたのは「シートカバー」。すでに購入済みで、「注文するのに4カ月かかった」と明かしました。",

  "そのほか、高速道路を走行中に石がぶつかったことから、車体を守るための泥よけを希望。さらに、ライトには鉄格子のようなデザインのカバーを取り付けたいと話しました。",

  "<strong>完成したデリカを披露</strong>その後、カスタムを終えたデリカをお披露目。みなみかわさんは、ライトに取り付けられたカバーを見ると、「絶対にナメられないですね、グラサンをかけているのと一緒ですね」と語りました。シートには雅代さんが希望していた「ベロアっぽいやつ」のカバーを取り付けました。",

  "ブラウン系のシートカバーに触れたみなみかわさんは、「あったかいすけどね、冬がちょうどいいですね」と満足げな様子を見せました。カスタムしたデリカに、コメント欄では「だいぶイカつくなった」「シートがオシャレ」などの声が寄せられています。",

  "デリカ（三菱・デリカ）は、1968年に登場した三菱自動車工業の自動車です。みなみかわさんが所有しているのは「デリカD:5　シャモニー」で、今年6月に自身のYouTubeチャンネルで購入したことを明かしていました。動画では、走行距離1万7000キロの中古車であることや、ローンの審査に通らなかったことを報告。「ナメられたくない」という理由から、雅代さんが一括で購入したことを明かし、話題になりました。"
]
