    id: "news26",
    title: "年に一度の贅沢!湖池屋「ピュアポテト 凄じゃが」3種が期間限定で新登場 北海道産ブランド芋×極上の味わい",
    date: "11/16（月）",
    image: "img/年に一度の贅沢!湖池屋「ピュアポテト 凄じゃが」3種が期間限定で新登場 北海道産ブランド芋×極上の味わい　ライフ.webp",
    imageClass: "img",
    paragraphs: [
  "湖池屋から、「ピュアポテト」ブランドより、“北海道産ブランドじゃがいも”3品種を使用した期間限定のポテトチップス「ピュアポテト 凄じゃが カニだし（きたかむい）/北海道産バター（ひかる）/焼きチーズ（サッシー）」を順次発売されます。",

  "<strong>3品種のじゃがいもを使用</strong>「じゃがいもの濃い旨みが楽しめる」と好評の「ピュアポテト」では、毎年秋冬限定で北海道産のブランド品種じゃがいもを使用し、各品種が持つ個性とおいしさをお届けする企画を展開しています。8年目となる今年は、第1弾として、旨みが特長のJAようてい産「きたかむい」と、甘みが特長のJA士幌町産「ひかる」を使用した2品が登場します。",

  "「ピュアポテト 凄じゃが カニだし（きたかむい）」は、凝縮された風味が、「きたかむい」の旨みを華やかに際立てます。北海道産の生乳を使用したバターのふくよかな濃厚さが特徴の「ピュアポテト 凄じゃが 北海道産バター（ひかる）」は、噛むほどに広がる「ひかる」の甘みを無限大に引き立てます。",

  "<strong>焼きチーズ味も順次発売</strong>「ピュアポテト 凄じゃが 焼きチーズ（サッシー）」は、酪農王国の北海道をイメージした“焼きチーズ”。熱々の鉄板でこんがりグリルしたような味わいが、「サッシー」の香ばしさを引き出します。",

  "【第1弾 商品概要】商品名/内容量は「ピュアポテト 凄じゃが カニだし（きたかむい）」/52g、「ピュアポテト 凄じゃが 北海道産バター（ひかる）」/52g。価格はオープン価格。発売日/販売先は2026年11月16日（月）/全国・コンビニエンスストア先行、2026年11月23日（月）/全国・スーパーマーケット他一般チャネル。",

  "【第2弾 商品概要】商品名/内容量は「ピュアポテト 凄じゃが 焼きチーズ（サッシー）」/52g。価格はオープン価格。発売日/販売先は2026年12月14日（月）/全国・コンビニエンスストア先行、2027年1月11日（月）/全国・スーパーマーケット他一般チャネル。"
]
