  "<strong>映画の世界を表現したイルミネーション</strong>日比谷ステップ広場には、映画をイメージし、オリジナルオーナメントを飾った高さ約8メートルのメインツリーが登場。フルカラーイルミネーションによる多彩な光が広場を染めている。また、「アベンジャーズ」の音楽と光を組み合わせた特別演出を30分に1回、約90秒間実施。",

