  "<strong>開催期間と点灯時間</strong>点灯時間は午後4時から午後11時まで。「『アベンジャーズ ドゥームズデイ』 presents HIBIYA Magic Time SQUARE 2026」は12月25日まで開催される。",

  "なお、現在ディズニープラスでは、「アベンジャーズ　ドゥームズデイ」鑑賞前に“見ておきたい作品”として、以下15タイトルをピックアップしている。",

