  "<strong>日本記録保持者からのエールと新たな目標</strong>授賞式では日本記録保持者の山縣亮太（セイコー）からサプライズのビデオメッセージが届いた。「これからも自分の可能性を信じて挑戦を続けてほしい。同じスプリンターとしてお互いを高め合いながら、日本の陸上界を一緒に盛り上げていける、そんな日を楽しみにしています」。",

