  "<strong>持続可能な観光地として評価</strong>100選は、地域の抱える課題を解決した「優良事例」としてオランダの非営利組織が認めるもので、2014年から毎年実施されている。6月に市観光協会がメールで書類を提出し、審査を経て決まった。",

  "柳川の掘割は市内に網の目のように張り巡らされ、総延長は930キロ。有明海沿いの水源に乏しい地域で、古来、雨水を蓄える「貯水池」として人々の暮らしを支えてきた。かつては「朝10時までは生活用の水だから泳がない」という暗黙のルールがあったという。有明海の満潮と大雨が重なった場合などに氾濫を防ぐ治水機能も果たしてきた。",

