  "どんこ舟による川下りは水郷・柳川の代名詞として定着。観光事業者らも年間約300万円を出し合い、掘割の清掃や維持管理に努めている。",

  "こうしたいきさつを書類にまとめた市観光協会の氏家将利さん（34）は「地域の生活文化を育んできた掘割の役割と価値を、多くの人に知ってもらいたかった」。中欧スロベニアのクラーニ市で10月下旬にあった表彰式には、市観光協会のスタッフや松永久市長も出席。松永市長は「掘割は市民が受け継いできた財産。世界中から愛される柳川のまちづくりを進めていく」と語る。"
