// 現在の実験で使用する記事セット
const articleSet = sessionStorage.getItem("articleSet");

// 記事セットA・Bを振り分ける
const currentNewsData = newsData.filter((news) => {

    const articleNumber = Number(news.id.replace("news", ""));

    if (articleSet === "A") {
        return articleNumber >= 1 && articleNumber <= 90;
    }

    if (articleSet === "B") {
        return articleNumber >= 91 && articleNumber <= 180;
    }

    return false;
});
